  'collecting-p1' => 'जब प्रतिक्रियाएँ कुशलतापूर्वक व्यवस्थित की जाती हैं तो भरने योग्य फॉर्म वास्तव में मूल्यवान हो जाते हैं। अलग-अलग पूर्ण पीडीएफ प्राप्त करने के बजाय, केंद्रीकृत प्रणालियों में प्रतिक्रियाएं व्यवस्थित करें।',
  'collecting-p2' => 'जब प्रपत्र डेटाबेस या स्प्रेडशीट से जुड़े होते हैं, तो प्रतिक्रियाएँ स्वचालित रूप से पॉप्युलेट हो जाती हैं। किसी मैन्युअल डेटा प्रविष्टि की आवश्यकता नहीं है.',
  'collecting-p3' => 'यदि प्रत्यक्ष ईमेल वितरण का उपयोग किया जा रहा है तो व्यक्तिगत रूप से ईमेल प्रतिक्रियाएँ। स्प्रेडशीट का उपयोग करके सबमिट की गई प्रतिक्रियाओं को ट्रैक करें।',
  'collecting-p4' => 'ऑनलाइन फॉर्म प्लेटफ़ॉर्म का उपयोग करें जो पूर्ण प्रतिक्रियाएँ, आंशिक प्रतिक्रियाएँ और अनुत्तरित सबमिशन दिखाने वाले प्रतिक्रिया डैशबोर्ड प्रदान करते हैं।',
  'security-heading' => 'प्रपत्र सुरक्षा संबंधी विचार',
  'security-p1' => 'फॉर्म कभी-कभी सामाजिक सुरक्षा नंबर, क्रेडिट कार्ड की जानकारी, या चिकित्सा विवरण जैसी संवेदनशील जानकारी एकत्र करते हैं।',
  'security-p2' => 'किसी भी वेब-आधारित फॉर्म वितरण के लिए HTTPS कनेक्शन का उपयोग करें। यह पारगमन में डेटा को एन्क्रिप्ट करता है।',
  'security-p3' => 'भरे हुए फॉर्म सुरक्षित रूप से संग्रहित करें। केवल अधिकृत कर्मियों तक ही पहुंच प्रतिबंधित करें।',
  'security-p4' => 'संग्रहित करते समय __SECURE_PDF_LINK__ पर विचार करें। पासवर्ड-सुरक्षित भंडारण अनधिकृत पहुंच को रोकता है।',
  'security-p5' => 'प्रासंगिक नियमों का अनुपालन करें. हेल्थकेयर प्रपत्रों को HIPAA अनुपालन की आवश्यकता है। वित्तीय प्रपत्रों को पीसीआई अनुपालन की आवश्यकता होती है।',
  'advanced-heading' => 'उन्नत प्रपत्र सुविधाएँ',
  'advanced-p1' => 'गतिशील प्रपत्र उपयोगकर्ता चयन पर प्रतिक्रिया देते हैं। जब कोई उपयोगकर्ता किसी विशिष्ट विकल्प का चयन करता है, तो संबंधित फ़ील्ड स्वचालित रूप से दिखाई देती हैं।',
  'advanced-p2' => 'परिकलित फ़ील्ड अन्य फ़ील्ड मानों के आधार पर स्वतः-पॉप्युलेट होती हैं। इकाई मूल्य और मात्रा से कुल लागत की गणना करने वाला एक फॉर्म मैन्युअल गणना को समाप्त कर देता है।',
  'advanced-p3' => 'सशर्त तर्क पिछले उत्तरों के आधार पर अलग-अलग फॉर्म अनुभाग दिखाता है। एक बीमा फॉर्म चयनित कवरेज प्रकार के आधार पर अलग-अलग प्रश्न पूछ सकता है।',
  'advanced-p4' => 'भुगतान एकीकरण उन फॉर्मों की अनुमति देता है जो सीधे भुगतान जानकारी एकत्र करते हैं। एप्लिकेशन, पंजीकरण और ऑर्डर के लिए उपयोगी।',
  'measuring-heading' => 'प्रपत्र प्रभावशीलता को मापना',
  'measuring-p1' => 'पूर्णता दर ट्रैक करें. फॉर्म शुरू करने वाले कितने प्रतिशत उपयोगकर्ता वास्तव में उन्हें पूरा करते हैं। कम पूर्णता दरें डिज़ाइन समस्याओं का संकेत देती हैं।',
  'measuring-p2' => 'प्रतिक्रिया समय की निगरानी करें. उपयोगकर्ताओं को फ़ॉर्म भरने में कितना समय लगता है. लंबे समय तक जटिलता या भ्रम का संकेत हो सकता है।',
  'measuring-p3' => 'त्रुटि दर का विश्लेषण करें. उपयोगकर्ता कितनी बार अमान्य डेटा सबमिट करते हैं. उच्च त्रुटि दरें अस्पष्ट फ़ील्ड या अपर्याप्त सत्यापन का संकेत देती हैं।',
  'measuring-p4' => 'उपयोगकर्ता प्रतिक्रिया का अनुरोध करें. उपयोगकर्ताओं से पूछें कि फ़ॉर्म के बारे में क्या भ्रमित करने वाली बात थी। भविष्य के संस्करणों को बेहतर बनाने के लिए फीडबैक का उपयोग करें।',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-p1' => 'भरने योग्य पीडीएफ पेशेवर उपस्थिति को बनाए रखते हुए डेटा संग्रह को सुव्यवस्थित करता है। प्रभावी फ़ॉर्म बनाने के लिए सावधानीपूर्वक डिज़ाइन, उचित फ़ील्ड कॉन्फ़िगरेशन और उचित वितरण विधियों की आवश्यकता होती है।',
  'conclusion-p2' => 'विशेषज्ञता विकसित करने के लिए सरल रूपों से शुरुआत करें। अपनी आवश्यकताओं और तकनीकी क्षमता से मेल खाने वाले उपकरणों का उपयोग करें। जटिल व्यावसायिक फ़ॉर्म के लिए Adobe Acrobat, सर्वेक्षण के लिए Google फ़ॉर्म, मध्यम जटिलता के लिए ऑनलाइन प्लेटफ़ॉर्म।',
  'conclusion-p3' => 'मैन्युअल डेटा प्रविष्टि को समाप्त करने के लिए प्रपत्रों को डेटाबेस या स्प्रेडशीट के साथ एकीकृत करें। वितरण से पहले भलीभांति परीक्षण कर लें। फ़ॉर्म में लगातार सुधार करने के लिए उपयोगकर्ता की प्रतिक्रिया एकत्र करें।',
  'conclusion-p4' => 'फॉर्म-आधारित दस्तावेज़ों को नियमित रूप से संभालने वाली टीमों के लिए, __WORKFLOW_LINK__ पर विचार करें जो पूर्ण किए गए फॉर्म को कुशलतापूर्वक व्यवस्थित और संग्रहित करते हैं।',
);
